import json, random, sys
sys.path.insert(0,'/workspace/tmp/t')
import fuzz
def why(doc):
    problems=[]
    origins={}
    for z in doc['zones']:
        o=z['origin'].lower()
        if o in origins: problems.append('dup origin')
        origins[o]=1
        for r in z['records']:
            ow=r['owner'].lower()
            labs=ow[:-1].split('.') if ow!='.' else []
            ol=o[:-1].split('.') if o!='.' else []
            if len(labs)<len(ol) or labs[len(labs)-len(ol):]!=ol: problems.append('owner above origin')
    # cname coexistence
    for z in doc['zones']:
        per={}
        for r in z['records']:
            per.setdefault(r['owner'].lower(),[]).append(r['type'])
        for ow,ts in per.items():
            if 'CNAME' in ts and len(ts)>1: problems.append('cname coexist '+ow)
            if 'CNAME' in ts and ow==z['origin'].lower(): problems.append('cname at origin')
    return problems
bad=0
for i in range(600):
    rng=random.Random(i); doc=fuzz.gen(rng)
    import subprocess
    p=subprocess.run([sys.executable,'-I','/workspace/submission/main.py'],input=json.dumps(doc).encode(),capture_output=True)
    out=p.stdout.decode()
    if out.startswith('{"error"'):
        w=why(doc)
        if not w:
            print('UNEXPLAINED rejection', i, json.dumps(doc)[:600]); bad+=1
            if bad>3: break
print('unexplained:', bad)
PYEOF
